function icon(name, cls = '') { return `<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name}"></use></svg>`; }
function escapeHtml(value = '') { return String(value).replace(/[&<>'"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[ch])); }
function L(en, bn) { return state.lang === 'bn' ? bn : en; }
function statusClass(status) { if (/Overdue|Escalated|Suspended|Error/i.test(status)) return 'danger'; if (/Pending|Waiting|Watch|High/i.test(status)) return 'warning'; if (/Completed|Verified|Active|On track/i.test(status)) return 'success'; if (/Assigned|Submitted|Review|In Progress/i.test(status)) return 'info'; return 'neutral'; }
function statusBadge(status) { return `<span class="status ${statusClass(status)}">${escapeHtml(status)}</span>`; }
function can(action) { if (state.role === 'System Administrator') return true; if (state.role === 'Supervisor') return !['manage-users', 'system-settings'].includes(action); return !['assign', 'escalate', 'manage-users', 'system-settings', 'org-report'].includes(action); }
function unreadCount() { return notifications.filter(n => !n.read).length; }
function focusKey(el) { if (!el || el === document.body) return null; if (el.id) return `#${el.id}`; if (el.dataset.action) return `[data-action="${el.dataset.action}"]`; if (el.dataset.column) return `[data-column="${el.dataset.column}"]`; return null; }
function pageTitle(page = state.page) { const x = labels[page] || labels.dashboard; return L(x[0], x[1]); }
function breadcrumb(page = state.page) { return `<div class="breadcrumbs"><span>${L('Workspace', 'কর্মক্ষেত্র')}</span>${icon('chevron')}<strong>${pageTitle(page)}</strong></div>`; }
function pageHead(title, description, actions = '', page = state.page) { return `<div class="page-head"><div>${breadcrumb(page)}<h1 class="page-title">${title}</h1><p class="page-description">${description}</p></div><div class="head-actions">${actions}</div></div>`; }
function metric(label, value, foot, tone = '') { return `<div class="panel metric-card ${tone}"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`; }
function button(label, cls = 'secondary', action = '', extra = '') { return `<button type="button" class="button ${cls}" ${action ? `data-action="${action}"` : ''} ${extra}>${label}</button>`; }
function selectField(label, name, options, value = '', required = false) { return `<div class="field"><label for="${name}">${label}${required ? ' <span class="required">*</span>' : ''}</label><select id="${name}" name="${name}">${options.map(o => `<option value="${escapeHtml(o[0])}" ${String(value) === String(o[0]) ? 'selected' : ''}>${escapeHtml(o[1])}</option>`).join('')}</select></div>`; }
function inputField(label, name, value = '', type = 'text', required = false, placeholder = '') { const error = state.registrationStep === 2 && required && !value; return `<div class="field ${error ? 'invalid' : ''}"><label for="${name}">${label}${required ? ' <span class="required">*</span>' : ''}</label><input id="${name}" name="${name}" type="${type}" value="${escapeHtml(value)}" placeholder="${placeholder}" ${required ? 'aria-required="true"' : ''}/>${error ? '<span class="error">This field is required.</span>' : ''}</div>`; }

function render() {
  const previousModal = state.renderedModal;
  const activeKey = focusKey(document.activeElement);
  const trigger = document.activeElement && document.activeElement !== document.body ? document.activeElement : state.lastActionEl;
  const returnKey = !previousModal && state.modal ? focusKey(trigger) : state.returnFocus;
  app.innerHTML = state.auth ? renderShell() : renderLogin();
  document.documentElement.lang = state.lang;
  state.renderedPage = state.page;
  state.renderedModal = state.modal ? state.modal.type : null;
  state.returnFocus = returnKey;
  if (state.modal) {
    app.querySelectorAll('.sidebar, .main-shell').forEach(el => el.setAttribute('inert', ''));
    if (!previousModal) app.querySelector('[role="dialog"] .close-btn')?.focus();
    else if (activeKey) app.querySelector(activeKey)?.focus();
  } else if (previousModal && returnKey) {
    app.querySelector(returnKey)?.focus();
  }
  bindDynamic();
}

