function renderShell() {
  return `<div class="app-shell"><aside class="sidebar" id="sidebar">${renderSidebar()}</aside><div class="sidebar-scrim" data-action="toggle-sidebar" aria-hidden="true"></div><section class="main-shell"><header class="topbar"><button class="menu-toggle" data-action="toggle-sidebar" aria-label="Open navigation">${icon('menu')}</button><div class="search-wrap">${icon('search')}<input id="global-search" aria-label="Global search" placeholder="Search cases… press Enter" /></div><div class="topbar-actions"><button class="lang-switch" data-action="toggle-lang" aria-label="Switch language">${state.lang === 'en' ? 'বাং' : 'EN'}</button><div class="language-toggle" aria-label="Language"><button data-lang="en" class="${state.lang === 'en' ? 'active' : ''}">EN</button><button data-lang="bn" class="${state.lang === 'bn' ? 'active' : ''}">বাং</button></div><button class="topbar-icon" data-page="notifications" aria-label="Notifications">${icon('bell')}${unreadCount() ? '<span class="notification-dot"></span>' : ''}</button><button class="profile-menu" data-action="sign-out" aria-label="Sign out of the demo"><div class="avatar">AR</div><div class="profile-copy"><div class="profile-name">A. Rahman</div><div class="profile-role">${state.role}</div></div>${icon('down','sm')}</button></div></header><main class="content" id="main-content">${renderPage()}</main><nav class="mobile-bottom" aria-label="Mobile navigation"><button data-page="dashboard" class="${state.page === 'dashboard' ? 'active' : ''}">${icon('grid')}<span>Home</span></button><button data-page="cases" class="${state.page === 'cases' ? 'active' : ''}">${icon('briefcase')}<span>Cases</span></button><button data-page="workflow" class="${state.page === 'workflow' ? 'active' : ''}">${icon('list')}<span>Queue</span></button><button data-page="notifications" class="${state.page === 'notifications' ? 'active' : ''}">${icon('bell')}<span>Alerts</span></button></nav></section></div>${state.modal ? renderModal() : ''}`;
}

function renderSidebar() {
  return `<div class="brand"><div class="brand-mark">M</div><div><div class="brand-title">MoHPW Case Monitoring</div><div class="brand-subtitle">Operation & Monitoring System</div></div></div><button class="sidebar-close" data-action="toggle-sidebar" aria-label="Close navigation">${icon('x')}</button><nav class="nav" aria-label="Primary navigation">${nav.map(group => `<div class="nav-section">${L(group.section, group.section === 'Workspace' ? 'কর্মক্ষেত্র' : group.section === 'Insights' ? 'বিশ্লেষণ' : group.section === 'Administration' ? 'প্রশাসন' : 'সহায়তা')}</div>${group.items.map(([page, ic, en, bn]) => `<button class="nav-item ${state.page === page ? 'active' : ''}" data-page="${page}">${icon(ic)}<span>${L(en, bn)}</span>${page === 'notifications' && unreadCount() ? `<span class="nav-count">${unreadCount()}</span>` : ''}</button>`).join('')}`).join('')}</nav><div class="sidebar-footer"><div class="demo-note">${icon('info','sm')}<span>Demo data only. This frontend does not provide backend security or persistence.</span></div></div>`;
}

function renderPage() {
  switch (state.page) {
    case 'dashboard': return renderDashboard(); case 'cases': return renderCases(); case 'registration': return renderRegistration(); case 'case-detail': return renderCaseDetail(); case 'workflow': return renderWorkflow(); case 'documents': return renderDocuments(); case 'calendar': return renderCalendar(); case 'reports': return renderReports(); case 'notifications': return renderNotifications(); case 'users': return renderUsers(); case 'settings': return renderSettings(); case 'help': return renderHelp(); default: return renderDashboard();
  }
}

