function filteredCases() {
  let list = cases.filter(c => {
    const q = state.caseQuery.toLowerCase();
    return (!q || [c.id,c.title,c.organization,c.assignee,c.category].some(v => v.toLowerCase().includes(q))) && (state.caseStatus === 'all' || c.status === state.caseStatus) && (state.casePriority === 'all' || c.priority === state.casePriority) && (state.caseOrg === 'all' || c.organization === state.caseOrg) && (state.savedView !== 'my' || c.assignee === 'A. Rahman') && (state.savedView !== 'overdue' || c.risk === 'Overdue' || c.status === 'Escalated');
  });
  list.sort((a,b) => String(a[state.sortBy]).localeCompare(String(b[state.sortBy])) * (state.sortDir === 'asc' ? 1 : -1)); return list;
}

function renderCases() {
  const list = filteredCases(); const perPage = 5; const pages = Math.max(1, Math.ceil(list.length / perPage)); state.casePage = Math.min(state.casePage, pages); const shown = list.slice((state.casePage-1)*perPage, state.casePage*perPage); const allShownSelected = shown.length > 0 && shown.every(c => state.selectedCases.includes(c.id));
  const col = key => state.columns[key] ? '' : 'style="display:none"';
  return `${pageHead(pageTitle(), L('Search, triage, assign, and export a working case register. The records below are fictional.', 'কাল্পনিক রেকর্ডের মামলা নিবন্ধনে অনুসন্ধান, বাছাই, দায়িত্ব ও এক্সপোর্ট করুন।'), `${button(`${icon('plus','sm')} Register case`, 'primary', 'go-registration')}${button(`${icon('download','sm')} Export`, 'secondary', 'export-cases')}`)}<section class="panel"><div class="table-toolbar"><div class="search-wrap">${icon('search')}<input data-filter="case-query" value="${escapeHtml(state.caseQuery)}" placeholder="Search by ID, title, organization…" aria-label="Search cases" /></div>${button(`${icon('filter','sm')} Filters`, 'secondary', 'toggle-filters')}${button('Columns', 'secondary', 'columns-modal')}${state.selectedCases.length ? `<span class="selected-count">${state.selectedCases.length} selected</span>${button('Bulk assign', 'ghost', 'bulk-assign')}${button('Archive', 'ghost', 'bulk-archive')}` : ''}<span class="toolbar-spacer"></span><span class="muted small-text">${list.length} results</span></div>${state.showFilters ? `<div class="filter-grid">${selectField('Status','case-status',[['all','All statuses'],['Under Review','Under Review'],['Pending Approval','Pending Approval'],['In Progress','In Progress'],['Escalated','Escalated'],['Completed','Completed']],state.caseStatus)}${selectField('Priority','case-priority',[['all','All priorities'],['High','High'],['Medium','Medium'],['Normal','Normal']],state.casePriority)}${selectField('Organization','case-org',[['all','All organizations'],['PWD','PWD'],['NHA','NHA'],['RAJUK','RAJUK'],['CDA','CDA'],['HBRI','HBRI'],['LGED','LGED']],state.caseOrg)}${selectField('Saved view','saved-view',[['all','Current filters'],['my','My assigned cases'],['overdue','Overdue & escalated']], state.savedView)}<div class="filter-actions">${button('Clear filters','ghost','clear-filters')}</div></div>` : ''}${shown.length ? `<div class="table-wrap"><table class="table"><thead><tr><th><input type="checkbox" data-select-all ${allShownSelected ? 'checked' : ''} aria-label="Select all visible cases" /></th>${[['id','Case ID'],['title','Case'],['organization','Organization'],['status','Status'],['priority','Priority'],['assignee','Responsible officer'],['deadline','Next deadline'],['updatedAt','Updated']].map(([key,label]) => `<th ${col(key)}><button class="button ghost small" data-sort="${key}">${label} ${state.sortBy === key ? (state.sortDir === 'asc' ? '↑' : '↓') : '↕'}</button></th>`).join('')}<th>Action</th></tr></thead><tbody>${shown.map(c => `<tr><td><input type="checkbox" data-case-select="${c.id}" ${state.selectedCases.includes(c.id) ? 'checked' : ''} aria-label="Select ${c.id}" /></td><td ${col('id')}><div class="case-cell"><a href="#" data-case="${c.id}"><strong>${c.id}</strong></a><span class="subline">${c.category}</span></div></td><td ${col('title')}><div class="case-cell"><a href="#" data-case="${c.id}"><strong>${escapeHtml(state.lang === 'bn' ? c.titleBn : c.title)}</strong></a><span>${escapeHtml(c.summary)}</span></div></td><td ${col('organization')}><strong>${c.organization}</strong><span class="subline">${c.court}</span></td><td ${col('status')}>${statusBadge(c.status)}</td><td ${col('priority')}><span class="priority ${c.priority.toLowerCase()}">${c.priority}</span>${c.risk === 'Overdue' ? `<span class="subline overdue">${icon('alert','sm')} ${c.risk}</span>` : ''}</td><td ${col('assignee')}>${c.assignee}</td><td ${col('deadline')}><strong class="${c.risk === 'Overdue' ? 'overdue' : ''}">${c.nextDeadline}</strong><span class="subline">${c.risk}</span></td><td ${col('updatedAt')}>${c.updatedAt}</td><td>${button(`${icon('eye','sm')} Open`, 'ghost small', `open-case:${c.id}`)}</td></tr>`).join('')}</tbody></table></div>${renderPagination(list.length,pages)}` : renderState('empty')}</section>`;
}

function renderPagination(total, pages) { return `<div class="pagination"><span>Showing ${total ? ((state.casePage-1)*5)+1 : 0}–${Math.min(state.casePage*5,total)} of ${total} cases</span><div class="page-buttons"><button class="page-btn" data-case-page="${Math.max(1,state.casePage-1)}" ${state.casePage === 1 ? 'disabled' : ''}>${icon('chevron','sm')}</button>${Array.from({length: pages}, (_,i) => `<button class="page-btn ${state.casePage === i+1 ? 'active' : ''}" data-case-page="${i+1}">${i+1}</button>`).join('')}<button class="page-btn" data-case-page="${Math.min(pages,state.casePage+1)}" ${state.casePage === pages ? 'disabled' : ''}>${icon('arrow','sm')}</button></div></div>`; }
function renderState(type) { if (type === 'loading') return `<div class="state-panel"><div><div class="skeleton skeleton-line" style="width:260px"></div><div class="skeleton skeleton-line short"></div><div class="skeleton skeleton-line" style="width:190px"></div></div></div>`; if (type === 'error') return `<div class="state-panel"><div class="error-box"><strong>${icon('alert','sm')} Could not load the case register</strong><p>Demo service response timed out. Try again, or continue with the saved local view.</p>${button('Try again','secondary','retry')}</div></div>`; if (type === 'permission') return `<div class="state-panel"><div class="permission-box"><strong>${icon('lock','sm')} Access restricted</strong><p>Your current role does not have permission to view this workspace. Ask a supervisor or system administrator to request access.</p>${button('Return to dashboard','secondary','go-dashboard')}</div></div>`; return `<div class="state-panel"><div><div class="state-icon">${icon('folder','lg')}</div><h3>No records match these filters</h3><p>Clear one or more filters to broaden the view. Saved views can be used for recurring triage work.</p>${button('Clear filters','secondary','clear-filters')}</div></div>`; }

function renderRegistration() {
  const d = state.registrationData; const step = state.registrationStep;
  const steps = [['1','Case details'],['2','Assignment & dates'],['3','Documents'],['4','Review & submit']];
  let body = '';
  if (step === 1) body = `<div class="form-grid">${inputField('Case title (English)','case-title',d.title||'','text',true,'Enter a concise case title')}${inputField('Case title (Bangla)','case-title-bn',d.titleBn||'','text',false,'বাংলায় শিরোনাম লিখুন')}${selectField('Organization','case-organization',[['','Select organization'],['PWD','Public Works Department'],['RAJUK','RAJUK'],['CDA','Chattogram Development Authority'],['NHA','National Housing Authority']],d.organization||'',true)}${selectField('Court or authority','case-court',[['','Select authority'],['High Court Division','High Court Division'],['Administrative Tribunal','Administrative Tribunal'],['District Court','District Court'],['Land Appeal Board','Land Appeal Board']],d.court||'',true)}${selectField('Case category','case-category',[['','Select category'],['Procurement','Procurement'],['Contract','Contract'],['Land & Property','Land & Property'],['Service','Service'],['Tender','Tender']],d.category||'',true)}${selectField('Priority','case-priority-form',[['High','High'],['Medium','Medium'],['Normal','Normal']],d.priority||'Normal',true)}<div class="field full"><label for="case-summary">Case summary <span class="required">*</span></label><textarea id="case-summary" name="summary" placeholder="Describe the matter in a few sentences">${escapeHtml(d.summary||'')}</textarea>${step === 1 && !d.summary ? '<span class="help">Required for review. Use plain language and avoid sensitive personal information in this demo.</span>' : ''}</div></div>`;
  if (step === 2) body = `<div class="form-grid">${selectField('Responsible officer','case-assignee',[['','Select officer'],['A. Rahman','A. Rahman'],['S. Karim','S. Karim'],['N. Sultana','N. Sultana'],['T. Ahmed','T. Ahmed']],d.assignee||'',true)}${inputField('Filing date','case-filingDate',d.filingDate||'2024-07-14','date',true)}${inputField('Next deadline','case-deadline',d.deadline||'','date',true)}${selectField('Related case (optional)','case-related',[['','No linked case'],['MHPW-2024-0187','MHPW-2024-0187'],['MHPW-2024-0182','MHPW-2024-0182']],d.related||'')}<div class="field full"><label for="case-instructions">Initial instructions</label><textarea id="case-instructions" name="instructions" placeholder="What should happen first?">${escapeHtml(d.instructions||'')}</textarea><span class="help">This becomes the first task in the case workflow.</span></div></div>`;
  if (step === 3) body = `<div class="upload-zone" data-upload-zone><input id="registration-upload" type="file" multiple accept=".pdf,.docx,.xlsx,.jpg,.jpeg,.png" /><label for="registration-upload">${icon('upload','lg')}<strong>Choose supporting files</strong><span>PDF, DOCX, XLSX, JPG, PNG • up to 10MB each</span></label></div><div class="section-heading" style="margin-top:20px"><div><h3>Attachments in this draft</h3><p>Files are local-only in this demonstration.</p></div></div><div class="review-list">${(d.files || []).length ? d.files.map(f => `<div class="review-row"><dt>${icon('file','sm')} ${escapeHtml(f.name)}</dt><dd>${f.size} <button class="button ghost small" data-remove-file="${escapeHtml(f.name)}">Remove</button></dd></div>`).join('') : `<div class="review-row"><dt>No files attached</dt><dd class="muted">Supporting documents can be added now or later.</dd></div>`}</div>`;
  if (step === 4) body = `<div class="alert-box" style="display:flex;gap:9px;padding:12px;border:1px solid #b7e3dc;background:#f0faf8;color:var(--teal);border-radius:5px;margin-bottom:16px">${icon('info','sm')} <span>Review the fictional record before submitting. Submission only updates local demo state.</span></div><dl class="review-list">${[['Case title',d.title||'Not provided'],['Organization',d.organization||'Not provided'],['Court / authority',d.court||'Not provided'],['Category',d.category||'Not provided'],['Priority',d.priority||'Not provided'],['Responsible officer',d.assignee||'Not provided'],['Filing date',d.filingDate||'Not provided'],['Next deadline',d.deadline||'Not provided'],['Summary',d.summary||'Not provided']].map(([a,b]) => `<div class="review-row"><dt>${a}</dt><dd>${escapeHtml(b)}</dd></div>`).join('')}</dl>`;
  return `${pageHead('Register a case', 'A guided intake flow with draft save, validation, evidence upload, and review-before-submit.', '')}<section class="panel panel-pad"><div class="steps">${steps.map((s,i) => `<div class="step ${step === i+1 ? 'active' : ''} ${step > i+1 ? 'done' : ''}"><span class="step-num">${step > i+1 ? icon('check','sm') : s[0]}</span><span class="step-label">${s[1]}</span></div>`).join('')}</div><div class="section-heading"><div><h2>${steps[step-1][1]}</h2><p>Step ${step} of 4 • Fields marked with * are required.</p></div><span class="demo-label">${icon('info','sm')} Local draft</span></div>${body}<div class="form-footer"><div>${button('Save draft','secondary','save-draft')}</div><div class="form-footer-right">${step > 1 ? button('Back','secondary','registration-back') : button('Cancel','ghost','go-dashboard')}${step < 4 ? button('Continue','primary','registration-next') : button('Submit case','primary','submit-registration')}</div></div></section>`;
}

function currentCase() { return cases.find(c => c.id === state.routeCase) || cases[0]; }
function renderCaseDetail() {
  const c = currentCase(); const tabs = [['summary','Summary'],['timeline','Timeline'],['tasks','Tasks'],['documents','Documents'],['notes','Notes & communications'],['audit','Audit history']];
  return `${pageHead('Case workspace', 'Central review workspace for what happened, what happens next, and who owns the next action.', `${button(`${icon('arrow','sm')} Back to cases`,'secondary','go-cases')}${button(`${icon('download','sm')} Export case`,'secondary','export-case')}`)}<section class="panel case-header"><div class="case-header-top"><div><div class="case-id">${c.id}</div><h2 class="case-heading">${escapeHtml(c.title)}</h2><div class="case-heading-bn">${escapeHtml(c.titleBn)}</div></div><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">${statusBadge(c.status)}<span class="priority ${c.priority.toLowerCase()}">${c.priority} priority</span>${c.risk === 'Escalated' ? '<span class="status danger">Escalated</span>' : ''}</div></div><div class="case-meta"><div class="case-meta-item"><span class="tiny-label">Organization</span><strong>${c.organization}</strong></div><div class="case-meta-item"><span class="tiny-label">Court / authority</span><strong>${c.court}</strong></div><div class="case-meta-item"><span class="tiny-label">Responsible officer</span><strong>${c.assignee}</strong></div><div class="case-meta-item"><span class="tiny-label">Next deadline</span><strong class="${c.risk === 'Overdue' ? 'overdue':''}">${c.nextDeadline}</strong></div><div class="case-meta-item"><span class="tiny-label">Last updated</span><strong>${c.updatedAt}</strong></div></div></section><section class="panel" style="margin-top:16px"><div class="tab-bar">${tabs.map(([t,l]) => `<button class="tab ${state.detailsTab===t?'active':''}" data-detail-tab="${t}">${l}</button>`).join('')}</div>${renderDetailTab(c)}</section>`;
}
function renderDetailTab(c) {
  if (state.detailsTab === 'summary') return `<div class="panel-pad"><div class="summary-grid"><div class="summary-block"><span class="tiny-label">Current stage</span><strong>Legal review</strong><p>2 of 4 workflow stages complete</p></div><div class="summary-block"><span class="tiny-label">Next action</span><strong>Confirm committee minutes</strong><p>Owner: S. Karim • due 18 Jul</p></div><div class="summary-block"><span class="tiny-label">Open risks</span><strong class="overdue">1 escalated item</strong><p>Deadline exception recorded</p></div></div><div class="detail-grid"><div><div class="section-heading" style="margin-top:22px"><div><h3>What happened</h3><p>Fictional case summary and latest movement</p></div></div><div class="note-box"><p>${escapeHtml(c.summary)} The record was moved to Under Review after the intake checklist was completed.</p><small>Last action: 04 Jul 2024 by A. Rahman</small></div><div class="section-heading" style="margin-top:22px"><div><h3>Workflow progress</h3><p>Current stage and required next step</p></div>${button('Open work queue','ghost small','go-workflow')}</div><div class="steps"><div class="step done"><span class="step-num">${icon('check','sm')}</span><span class="step-label">Registered</span></div><div class="step done"><span class="step-num">${icon('check','sm')}</span><span class="step-label">Assigned</span></div><div class="step active"><span class="step-num">3</span><span class="step-label">Legal review</span></div><div class="step"><span class="step-num">4</span><span class="step-label">Decision</span></div></div></div><aside><div class="section-heading"><div><h3>Open tasks</h3><p>2 assigned actions</p></div></div><div class="task-list"><div class="task-row"><div><strong>Confirm committee minutes</strong><span>S. Karim • due 18 Jul 2024</span></div>${statusBadge('Pending Approval')}</div><div class="task-row"><div><strong>Verify response correspondence</strong><span>A. Rahman • due 16 Jul 2024</span></div>${statusBadge('In Progress')}</div></div><div class="section-heading" style="margin-top:18px"><div><h3>Missing evidence</h3><p>Required before decision</p></div></div><div class="note-box" style="border-left-color:var(--warning);background:var(--warning-bg)"><p>Committee attendance sheet is not attached.</p><small>Request from PWD records desk</small></div></aside></div></div>`;
  if (state.detailsTab === 'timeline') return `<div class="panel-pad"><div class="section-heading"><div><h2>Case timeline</h2><p>Chronological history of the fictional record</p></div>${button('Add timeline note','secondary','toast:Timeline note action is available in the production integration')}</div><div class="timeline">${[['04 Jul 2024','Moved to Under Review','A. Rahman completed the intake checklist and routed the file to legal review.','done'],['03 Jul 2024','Assignment accepted','S. Karim accepted responsibility for the legal review stage.','done'],['28 Jun 2024','Evidence uploaded','Supporting schedule.xlsx was added to the document set.','done'],['12 Jun 2024','Case registered','Initial case record created by A. Rahman.','done']].map(i=>`<div class="timeline-item"><div class="timeline-marker ${i[3]}">${icon('check','sm')}</div><div class="timeline-time">${i[0]}</div><div class="timeline-copy"><strong>${i[1]}</strong><p>${i[2]}</p></div></div>`).join('')}</div></div>`;
  if (state.detailsTab === 'tasks') return `<div class="panel-pad"><div class="section-heading"><div><h2>Tasks and assignments</h2><p>Make ownership and deadlines visible at a glance.</p></div>${button(`${icon('plus','sm')} Add task`,'primary','toast:Task created in local demo')}</div><div class="task-list"><div class="task-row"><div><strong>Confirm committee minutes</strong><span>Stage: Legal review • Owner: S. Karim • Due: 18 Jul 2024</span></div><div class="task-actions">${statusBadge('Pending Approval')}${button('Reassign','ghost small','toast:Reassignment flow opened')}</div></div><div class="task-row"><div><strong>Verify response correspondence</strong><span>Stage: Legal review • Owner: A. Rahman • Due: 16 Jul 2024</span></div><div class="task-actions">${statusBadge('In Progress')}${button('Complete','ghost small','complete-task')}</div></div><div class="task-row"><div><strong>Prepare decision brief</strong><span>Stage: Decision • Owner: Unassigned • Due: 25 Jul 2024</span></div><div class="task-actions">${statusBadge('Not started')}${button('Assign','ghost small','assign-task')}</div></div></div></div>`;
  if (state.detailsTab === 'documents') return renderDocuments(true);
  if (state.detailsTab === 'notes') return `<div class="panel-pad"><div class="section-heading"><div><h2>Notes & communications</h2><p>Internal notes and outbound correspondence log</p></div>${button(`${icon('plus','sm')} Add note`,'primary','toast:Note saved in local demo')}</div><div class="note-box"><p>“Please verify the committee attendance sheet before routing for decision.”</p><small>Internal note • S. Karim • 04 Jul 2024</small></div><div class="activity-list" style="margin-top:18px"><div class="activity-row"><span class="activity-dot blue"></span><div class="activity-copy"><strong>Request for records sent</strong><span>To: PWD records desk • Ref: OUT-2024-031</span><span>03 Jul 2024, 15:22</span></div></div><div class="activity-row"><span class="activity-dot"></span><div class="activity-copy"><strong>Clarification received</strong><span>Response received and attached to the case record.</span><span>02 Jul 2024, 12:10</span></div></div></div></div>`;
  return `<div class="panel-pad"><div class="section-heading"><div><h2>Audit history</h2><p>Who changed what and when</p></div>${statusBadge('Read-only view')}</div><div class="table-wrap"><table class="table" style="min-width:600px"><thead><tr><th>Timestamp</th><th>Actor</th><th>Action</th><th>Source</th></tr></thead><tbody>${[['04 Jul 2024 09:44','A. Rahman','Status changed to Under Review','Case workspace'],['04 Jul 2024 09:41','A. Rahman','Checklist marked complete','Workflow'],['03 Jul 2024 16:12','S. Karim','Assignment accepted','Work queue'],['28 Jun 2024 13:17','A. Rahman','Uploaded Supporting schedule.xlsx','Documents']].map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;
}

function renderWorkflow() {
  if (!can('assign') && state.role === 'Case Handler') { return `${pageHead('Work queue','Your assigned tasks, deadlines, and action history in one operational view.')}${renderState('permission')}`; }
  const columns = [['New','2'],['In Progress','3'],['Waiting for Information','2'],['Pending Approval','2']];
  return `${pageHead('Work queue', 'Manage workflow stages, ownership, due dates, approval status, and escalation cues.', `${button(`${icon('plus','sm')} Create task`,'primary','toast:Task creation opened')}${button(`${icon('download','sm')} Export queue`,'secondary','export-workflow')}`)}<div class="metric-grid">${metric('My open tasks','7','2 due this week','navy')}${metric('Due today','1','Needs attention','danger')}${metric('Awaiting review','4','Across 3 organizations','warning')}${metric('Completed this month','29','↑ 6 vs last month','teal')}${metric('Escalated','2','Supervisor view required','danger')}</div><section class="panel panel-pad"><div class="section-heading"><div><h2>Workflow board</h2><p>Fictional task queue • updated 14 Jul 2024, 10:20</p></div><div style="display:flex;gap:7px">${button('List view','secondary','toast:List view selected')}${button('Board view','primary','toast:Board view selected')}</div></div><div class="workflow-board">${columns.map(([title,count],idx) => `<div class="workflow-column ${idx===1?'current':''}"><h3>${title} <span class="muted">(${count})</span></h3>${[['Confirm committee minutes','MHPW-2024-0182','S. Karim','18 Jul'],['Verify response correspondence','MHPW-2024-0187','A. Rahman','16 Jul'],['Prepare decision brief','MHPW-2024-0176','M. Hossain','25 Jul']].slice(0,idx===0?2:idx===1?3:idx===2?2:2).map((x,i)=>`<div class="workflow-card"><strong>${x[0]}</strong><span>${x[1]}</span><span>${x[2]} • due ${x[3]}</span>${i===0&&idx===1?'<span class="status warning" style="margin-top:8px">Needs review</span>':''}</div>`).join('')}</div>`).join('')}</div></section><section class="panel panel-pad" style="margin-top:16px"><div class="section-heading"><div><h2>Action history</h2><p>Recent workflow transitions and approvals</p></div></div><div class="table-wrap"><table class="table" style="min-width:700px"><thead><tr><th>Case</th><th>Action</th><th>Actor</th><th>Time</th><th>Status</th></tr></thead><tbody>${[['MHPW-2024-0187','Moved to legal review','A. Rahman','Today, 09:44','Under Review'],['MHPW-2024-0182','Approval requested','S. Karim','Yesterday, 16:42','Pending Approval'],['MHPW-2024-0142','Assignment accepted','R. Kabir','Yesterday, 11:08','Assigned']].map(r=>`<tr><td><a href="#" data-case="${r[0]}">${r[0]}</a></td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td>${statusBadge(r[4])}</td></tr>`).join('')}</tbody></table></div></section>`;
}

function renderDocuments(inCase = false) {
  const docs = inCase ? documents : documents.concat([{ id:'DOC-861', name:'Site inspection photographs.zip', category:'Site evidence', type:'ZIP', size:'5.2 MB', uploadedAt:'20 Jun 2024', uploadedBy:'Records desk', version:'v1.0', confidentiality:'Restricted', verification:'Verified', required:false }]);
  return `${inCase ? '' : pageHead('Document centre','Manage document metadata, versions, verification, confidentiality, previews, and missing-evidence warnings.',`${button(`${icon('upload','sm')} Upload document`,'primary','upload-document')}${button(`${icon('download','sm')} Export index`,'secondary','export-documents')}`)}<div class="panel ${inCase?'':'panel-pad'}">${inCase ? `<div class="panel-pad"><div class="section-heading"><div><h2>Case documents</h2><p>4 files linked to ${currentCase().id}</p></div>${button('Upload','primary','upload-document')}</div>` : ''}<div class="table-wrap"><table class="table"><thead><tr><th>Document</th><th>Category</th><th>Version</th><th>Uploaded</th><th>Confidentiality</th><th>Verification</th><th>Access</th><th></th></tr></thead><tbody>${docs.map(d=>`<tr><td><div class="case-cell"><strong>${icon('file','sm')} ${escapeHtml(d.name)}</strong><span>${d.type} · ${d.size}</span></div></td><td>${d.category}</td><td><strong>${d.version}</strong><span class="subline">2 versions</span></td><td>${d.uploadedAt}<span class="subline">${d.uploadedBy}</span></td><td>${d.confidentiality === 'Restricted' ? statusBadge('Restricted') : statusBadge('Internal')}</td><td>${statusBadge(d.verification)}</td><td>${d.required ? '<span class="status warning">Required</span>' : '<span class="status neutral">Optional</span>'}</td><td>${button(`${icon('eye','sm')} Preview`,'ghost small',`preview-doc:${d.id}`)}</td></tr>`).join('')}</tbody></table></div>${inCase?'</div>':''}</div>${!inCase ? `<div class="detail-grid" style="margin-top:16px"><section class="panel panel-pad"><div class="section-heading"><div><h2>Missing-document warnings</h2><p>Required evidence across active demo cases</p></div></div><div class="notice-list"><div class="notice-row"><span class="state-icon" style="width:30px;height:30px;margin:0;color:var(--warning);background:var(--warning-bg)">${icon('alert','sm')}</span><div class="notice-copy"><strong>Committee attendance sheet</strong><span>MHPW-2024-0187 • Required before decision stage</span></div>${button('Open case','ghost small','open-case:MHPW-2024-0187')}</div><div class="notice-row"><span class="state-icon" style="width:30px;height:30px;margin:0;color:var(--danger);background:var(--danger-bg)">${icon('alert','sm')}</span><div class="notice-copy"><strong>Response correspondence</strong><span>MHPW-2024-0168 • Overdue escalation</span></div>${button('Open case','ghost small','open-case:MHPW-2024-0168')}</div></div></section><section class="panel panel-pad"><div class="section-heading"><div><h2>Upload validation</h2><p>Frontend rules applied before integration</p></div></div><div class="note-box"><p>Accepted: PDF, DOCX, XLSX, JPG, PNG. Maximum 10MB per file. Server-side malware scanning and access checks are integration responsibilities.</p><small>Use the Upload document action to test the validation feedback.</small></div></section></div>` : ''}`;
}

function renderCalendar() { return `${pageHead('Calendar & deadlines','A compact deadline view for task review, escalations, and planning.',`${button(`${icon('plus','sm')} Add deadline`,'primary','toast:Deadline creation opened')}${button(`${icon('print','sm')} Print view`,'secondary','print')}`)}<div class="detail-grid"><section class="panel panel-pad"><div class="section-heading"><div><h2>July 2024</h2><p>Fictional deadline calendar • all dates in local office time</p></div>${button('Today','secondary','toast:Jumped to today')}</div><div style="display:grid;grid-template-columns:repeat(7,1fr);border:1px solid var(--border)">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div style="padding:9px;border-bottom:1px solid var(--border);color:var(--muted);font-size:10px;font-weight:800;text-align:center">${d}</div>`).join('')}${Array.from({length:35},(_,i)=>{const day=i-1; const mark=[9,16,18,22,25].includes(day); return `<div style="min-height:72px;padding:8px;border-right:1px solid var(--border);border-bottom:1px solid var(--border);background:${day===14?'#edf3ff':'#fff'}"><span style="font-size:11px;color:${day<1?'var(--muted-2)':'var(--navy)'};font-weight:${day===14?'800':'500'}">${day>0?day:''}</span>${mark?`<div style="margin-top:8px;padding:4px;background:${day===9?'var(--danger-bg)':'var(--warning-bg)'};color:${day===9?'var(--danger)':'var(--warning)'};font-size:9px;border-radius:3px">${day===9?'Overdue':'Case task'}</div>`:''}</div>`}).join('')}</div></section><aside class="panel panel-pad"><div class="section-heading"><div><h2>Upcoming</h2><p>Prioritized by risk</p></div></div><div class="deadline-list">${[['09 Jul','MHPW-2024-0168','Overdue','danger'],['16 Jul','MHPW-2024-0176','Due in 2 days','warning'],['18 Jul','MHPW-2024-0187','Due in 4 days',''],['22 Jul','MHPW-2024-0182','Due in 8 days','']].map(r=>`<div class="deadline-row"><div class="date-box"><strong>${r[0].split(' ')[0]}</strong><span>${r[0].split(' ')[1]}</span></div><div class="deadline-copy"><strong>${r[1]}</strong><span class="${r[3]==='danger'?'overdue':''}">${r[2]}</span></div></div>`).join('')}</div></aside></div>`; }

function renderReports() { return `${pageHead('Reports & analytics','Export-ready operational views for volume, status, workload, and deadline compliance.',`${button(`${icon('download','sm')} Export report`,'primary','export-report')}${button(`${icon('print','sm')} Print`,'secondary','print')}`)}<section class="panel"><div class="filter-grid">${selectField('Organization','report-org',[['all','All organizations'],['PWD','PWD'],['RAJUK','RAJUK'],['NHA','NHA']], 'all')}${selectField('Case type','report-type',[['all','All case types'],['Procurement','Procurement'],['Land & Property','Land & Property'],['Contract','Contract']], 'all')}${selectField('Status','report-status',[['all','All statuses'],['Active','Active cases'],['Completed','Completed']], 'all')}${inputField('From','report-from','2024-01-01','date')}${inputField('To','report-to','2024-07-14','date')}<div class="filter-actions">${button('Apply filters','primary','toast:Report filters applied')}</div></div></section><div class="dashboard-grid" style="margin-top:16px"><section class="panel panel-pad"><div class="section-heading"><div><h2>Monthly case trend</h2><p>Registered vs closed • Jan–Jul 2024</p></div></div><div class="line-chart" role="img" aria-label="Line chart: registered and closed cases by month, January to July 2024"><svg viewBox="0 0 600 150" preserveAspectRatio="none"><path d="M5 118 L100 105 L195 110 L290 82 L385 91 L480 55 L595 42"/><path d="M5 132 L100 125 L195 121 L290 116 L385 106 L480 98 L595 84" style="stroke:#0f766e;stroke-dasharray:6 5"/>${[[5,118],[100,105],[195,110],[290,82],[385,91],[480,55],[595,42]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4"/>`).join('')}</svg></div><div class="chart-labels"><span>Jan</span><span>Feb</span><span>Mar</span><span>Apr</span><span>May</span><span>Jun</span><span>Jul</span></div><div class="legend"><span><i></i> Registered</span><span><i class="alt" style="background:var(--teal)"></i> Closed</span></div></section><section class="panel panel-pad"><div class="section-heading"><div><h2>Status distribution</h2><p>All active demo records</p></div></div><div class="donut-wrap"><div class="donut" role="img" aria-label="Status distribution: 36 percent under review, 26 percent in progress, 20 percent pending approval, 18 percent other"></div><div class="legend-list"><div><i></i> Under review <strong>36%</strong></div><div><i class="teal"></i> In progress <strong>26%</strong></div><div><i class="gray"></i> Pending approval <strong>20%</strong></div><div><i class="light"></i> Other <strong>18%</strong></div></div></div></section></div><section class="panel panel-pad"><div class="section-heading"><div><h2>Organization performance</h2><p>Pending, overdue, and completed counts for the selected period</p></div></div><div class="table-wrap"><table class="table" style="min-width:650px"><thead><tr><th>Organization</th><th>Total</th><th>Active</th><th>Overdue</th><th>Avg. workflow days</th><th>Completion</th></tr></thead><tbody>${[['PWD','82','57','3','18.4','69%'],['RAJUK','61','44','2','21.1','72%'],['NHA','48','31','1','16.8','78%'],['CDA','35','28','2','25.6','61%']].map(r=>`<tr>${r.map((x,i)=>`<td class="${i===4?'muted':''}">${i===0?`<strong>${x}</strong>`:x}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`; }

function renderNotifications() { const list = notifications.filter(n => state.noticeFilter === 'all' || (state.noticeFilter === 'unread' ? !n.read : n.type === state.noticeFilter)); return `${pageHead('Notifications','Deadlines, assignments, document events, and review requests for your workspace.',`${button('Mark all as read','secondary','mark-all-read')}`)}<section class="panel panel-pad"><div class="table-toolbar" style="margin:-20px -20px 10px"><button class="button ${state.noticeFilter==='all'?'primary':'secondary'} small" data-notice-filter="all">All</button><button class="button ${state.noticeFilter==='unread'?'primary':'secondary'} small" data-notice-filter="unread">Unread (${unreadCount()})</button><button class="button ${state.noticeFilter==='danger'?'primary':'secondary'} small" data-notice-filter="danger">Deadlines</button><span class="toolbar-spacer"></span><span class="muted small-text">Notifications are fictional demo events</span></div>${list.map(n=>`<div class="notification-item ${n.read?'':'unread'}"><div class="notification-icon ${n.type}">${icon(n.type === 'danger' ? 'alert' : n.type === 'warning' ? 'clock' : n.type === 'success' ? 'check' : 'info','sm')}</div><div class="notification-copy"><strong>${n.title}</strong><p>${n.body}</p><small>${n.time}</small></div><div>${n.caseId ? button('Open case','ghost small',`open-case:${n.caseId}`) : ''}${!n.read ? button('Mark read','ghost small',`mark-read:${n.id}`) : ''}</div></div>`).join('') || renderState('empty')}</section>`; }

function renderUsers() { if (!can('manage-users')) return `${pageHead('Users & roles','Manage access, role assignment, and account status for the demonstration workspace.')}${renderState('permission')}`; return `${pageHead('Users & roles','Manage access, role assignment, and account status for the demonstration workspace.',`${button(`${icon('plus','sm')} Add user`,'primary','toast:User invite flow opened')}${button(`${icon('download','sm')} Export users`,'secondary','export-users')}`)}<section class="panel"><div class="table-toolbar"><div class="search-wrap">${icon('search')}<input placeholder="Search name, email, organization…" aria-label="Search users" /></div><span class="toolbar-spacer"></span><span class="muted small-text">4 demo accounts</span></div><div class="table-wrap"><table class="table" style="min-width:720px"><thead><tr><th>User</th><th>Organization</th><th>Role</th><th>Status</th><th>Last active</th><th>Actions</th></tr></thead><tbody>${users.map(u=>`<tr><td><div style="display:flex;gap:9px;align-items:center"><div class="avatar">${u.name.split(' ').map(x=>x[0]).join('')}</div><div><strong>${u.name}</strong><span class="subline">${u.email}</span></div></div></td><td>${u.organization}</td><td><select data-role-user="${u.id}" aria-label="Role for ${u.name}"><option ${u.role==='Case Handler'?'selected':''}>Case Handler</option><option ${u.role==='Supervisor'?'selected':''}>Supervisor</option><option ${u.role==='Viewer'?'selected':''}>Viewer</option><option ${u.role==='System Administrator'?'selected':''}>System Administrator</option></select></td><td>${statusBadge(u.status)}</td><td>${u.lastActive}</td><td>${button('View access','ghost small','toast:Access profile opened')}</td></tr>`).join('')}</tbody></table></div></section>`; }

function renderSettings() { if (!can('system-settings')) return `${pageHead('System settings','Configure language, notification, and integration preferences for the demo workspace.')}${renderState('permission')}`; const tabs = [['general','General'],['notifications','Notifications'],['security','Security & integrations']]; return `${pageHead('System settings','Configure language, notification, and integration preferences for the demo workspace.',button('Save settings','primary','save-settings'))}<div class="settings-grid"><section class="panel settings-nav">${tabs.map(([t,l])=>`<button class="${state.settingsTab===t?'active':''}" data-settings-tab="${t}">${l}</button>`).join('')}</section><section class="panel panel-pad">${state.settingsTab==='general'?`<div class="section-heading"><div><h2>General preferences</h2><p>Workspace defaults for the frontend demonstration.</p></div></div><div class="setting-row"><div><strong>Default language</strong><p>Choose the display language for navigation and page labels.</p></div><select style="width:180px;min-height:36px" data-setting="language"><option>English</option><option>বাংলা</option></select></div><div class="setting-row"><div><strong>Use compact table density</strong><p>Show more records in operational lists on desktop.</p></div><button class="toggle on" data-toggle="compact" aria-label="Toggle compact table density"></button></div><div class="setting-row"><div><strong>Demo data banner</strong><p>Keep a visible banner wherever fictional data is shown.</p></div><button class="toggle on" data-toggle="demo" aria-label="Toggle demo data banner"></button></div>`:state.settingsTab==='notifications'?`<div class="section-heading"><div><h2>Notification preferences</h2><p>Choose which operational signals appear in your alert centre.</p></div></div>${[['Deadline reminders','Receive reminders 3 days before a deadline.'],['Assignment changes','Notify when a case or task is assigned to you.'],['Document verification','Notify when a document changes verification status.']].map((x,i)=>`<div class="setting-row"><div><strong>${x[0]}</strong><p>${x[1]}</p></div><button class="toggle ${i<2?'on':''}" data-toggle="notice-${i}" aria-label="Toggle ${x[0]}"></button></div>`).join('')}`:`<div class="section-heading"><div><h2>Security & integrations</h2><p>Integration points to be implemented by the backend team.</p></div></div><div class="note-box"><p>SSO/OIDC, MFA, server-side authorization, encrypted storage, malware scanning, retention policy, and immutable audit logs are not implemented in this frontend demo.</p><small>See README.md for the integration checklist.</small></div><div class="setting-row"><div><strong>Identity provider</strong><p>Not connected in demonstration mode.</p></div>${statusBadge('Not connected')}</div><div class="setting-row"><div><strong>API environment</strong><p>Local static demo • no persistence.</p></div>${statusBadge('Demo only')}</div>`}</section></div>`; }

function renderHelp() { return `${pageHead('Help & manuals','Short guides for common operational actions and the boundary between this demo and a production integration.') }<div class="dashboard-grid"><section class="panel panel-pad"><div class="section-heading"><div><h2>Common tasks</h2><p>Use these guides to understand the demo workflow.</p></div></div><div class="task-list">${[['Register a case','Start with the guided intake, save a draft, attach evidence, and submit after review.'],['Review a deadline','Open Calendar & deadlines or use the deadline cards on the dashboard.'],['Verify a document','Open Documents, inspect metadata, and use Preview to review a fictional file record.'],['Change ownership','Supervisors can use Work queue and the Assign action to update responsibility.']].map(x=>`<div class="task-row"><div><strong>${x[0]}</strong><span>${x[1]}</span></div>${button('Open','ghost small','toast:Guide opened')}</div>`).join('')}</div></section><section class="panel panel-pad"><div class="section-heading"><div><h2>Accessibility notes</h2><p>Keyboard and screen-reader conscious demo behavior.</p></div></div><div class="notice-list"><div class="notice-row"><span class="state-icon" style="width:30px;height:30px;margin:0">${icon('check','sm')}</span><div class="notice-copy"><strong>Visible focus</strong><span>All controls use a high-contrast focus ring.</span></div></div><div class="notice-row"><span class="state-icon" style="width:30px;height:30px;margin:0">${icon('check','sm')}</span><div class="notice-copy"><strong>Status text</strong><span>Color is paired with labels and symbols.</span></div></div><div class="notice-row"><span class="state-icon" style="width:30px;height:30px;margin:0">${icon('check','sm')}</span><div class="notice-copy"><strong>Reduced motion</strong><span>Shimmer and transitions honor the user preference.</span></div></div></div></section></div>`; }

function renderModal() {
  if (state.modal.type === 'columns') return `<div class="modal-backdrop" data-close-modal><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">Choose visible columns</h2><button class="close-btn" data-close-modal aria-label="Close">${icon('x')}</button></div><div class="modal-body"><p class="muted small-text">Keep the fields most useful for your current triage view.</p><div class="settings-grid" style="grid-template-columns:1fr 1fr;gap:8px">${Object.keys(state.columns).map(k=>`<label style="display:flex;gap:8px;align-items:center;padding:9px;border:1px solid var(--border);border-radius:4px;font-size:12px"><input type="checkbox" data-column="${k}" ${state.columns[k]?'checked':''}/> ${k === 'updatedAt' ? 'Updated' : k[0].toUpperCase()+k.slice(1)}</label>`).join('')}</div></div><div class="modal-foot">${button('Done','primary','close-modal')}</div></div></div>`;
  if (state.modal.type === 'upload') return `<div class="modal-backdrop" data-close-modal><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">Upload document</h2><p class="muted small-text" style="margin:4px 0 0">Frontend validation before a production storage integration.</p></div><button class="close-btn" data-close-modal aria-label="Close">${icon('x')}</button></div><div class="modal-body"><div class="upload-zone"><input id="doc-upload" type="file" accept=".pdf,.docx,.xlsx,.jpg,.jpeg,.png" /><label for="doc-upload">${icon('upload','lg')}<strong>Choose a file</strong><span>PDF, DOCX, XLSX, JPG, PNG • up to 10MB</span></label></div><div class="note-box" style="margin-top:16px"><p>Access restrictions, malware scanning, retention policy, and version storage are integration responsibilities.</p><small>Files are not transmitted or persisted by this frontend.</small></div></div><div class="modal-foot">${button('Close','primary','close-modal')}</div></div></div>`;
  if (state.modal.type === 'preview') { const d = documents.find(x=>x.id===state.modal.id) || documents[0]; return `<div class="modal-backdrop" data-close-modal><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">Document preview</h2><p class="muted small-text" style="margin:4px 0 0">${escapeHtml(d.name)} • ${d.version}</p></div><button class="close-btn" data-close-modal aria-label="Close">${icon('x')}</button></div><div class="modal-body"><div style="min-height:250px;display:grid;place-items:center;border:1px solid var(--border);background:repeating-linear-gradient(0deg,#fff,#fff 25px,#f5f7fa 26px);text-align:center"><div><div class="state-icon">${icon('file','lg')}</div><h3 style="margin:0;color:var(--navy)">Preview placeholder</h3><p class="muted small-text">The production integration will render the secured file here.</p></div></div><dl class="review-list" style="margin-top:16px">${[['Category',d.category],['Uploaded by',d.uploadedBy],['Uploaded',d.uploadedAt],['Confidentiality',d.confidentiality],['Verification',d.verification]].map(x=>`<div class="review-row"><dt>${x[0]}</dt><dd>${x[1]}</dd></div>`).join('')}</dl></div><div class="modal-foot">${button(`${icon('download','sm')} Download`, 'secondary', 'toast:Download requested in local demo')}${button('Close','primary','close-modal')}</div></div></div>`; }
  if (state.modal.type === 'confirm') return `<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">Confirm action</h2><button class="close-btn" data-close-modal aria-label="Close">${icon('x')}</button></div><div class="modal-body"><p>${state.modal.message}</p><p class="muted small-text">This changes only the in-memory demonstration state.</p></div><div class="modal-foot">${button('Cancel','secondary','close-modal')}${button('Confirm','danger',state.modal.action)}</div></div></div>`;
  return '';
}

function toast(message, error = false) {
  const node = document.createElement('div');
  node.className = `toast ${error ? 'error' : ''}`;
  node.innerHTML = icon(error ? 'alert' : 'check', 'sm');
  const text = document.createElement('span');
  text.textContent = message;
  node.appendChild(text);
  toastRegion.appendChild(node);
  setTimeout(() => node.remove(), 3600);
}
function update() {
  const pageChanged = state.renderedPage !== state.page;
  render();
  if (pageChanged) {
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    window.scrollTo({ top: 0, behavior: reduced ? 'auto' : 'smooth' });
  }
}
function collectRegistration() { app.querySelectorAll('[name]').forEach(el => { if (el.name.startsWith('login')) return; state.registrationData[el.name.replace(/^case-/, '')] = el.value; }); }

function bindDynamic() {
  app.querySelector('#login-form')?.addEventListener('submit', e => { e.preventDefault(); app.querySelector('[data-action="login"]')?.click(); });
  app.querySelector('#global-search')?.addEventListener('keydown', e => { if (e.key !== 'Enter') return; state.caseQuery = e.target.value.trim(); state.casePage = 1; state.page = 'cases'; update(); });
  app.querySelectorAll('[data-page]').forEach(el => el.addEventListener('click', ev => { ev.preventDefault(); state.page = el.dataset.page; state.modal = null; update(); }));
  app.querySelectorAll('[data-lang]').forEach(el => el.addEventListener('click', () => { state.lang = el.dataset.lang; update(); }));
  app.querySelectorAll('[data-role]').forEach(el => el.addEventListener('click', () => { state.role = el.dataset.role; app.querySelector('#login-role').value = state.role; toast(`Preview role set to ${state.role}`); }));
  app.querySelectorAll('[data-case]').forEach(el => el.addEventListener('click', ev => { ev.preventDefault(); state.routeCase = el.dataset.case; state.page = 'case-detail'; state.detailsTab='summary'; update(); }));
  app.querySelectorAll('[data-detail-tab]').forEach(el => el.addEventListener('click', () => { state.detailsTab = el.dataset.detailTab; update(); }));
  app.querySelectorAll('[data-settings-tab]').forEach(el => el.addEventListener('click', () => { state.settingsTab = el.dataset.settingsTab; update(); }));
  app.querySelectorAll('[data-case-select]').forEach(el => el.addEventListener('change', () => { state.selectedCases = el.checked ? [...new Set([...state.selectedCases, el.dataset.caseSelect])] : state.selectedCases.filter(x=>x!==el.dataset.caseSelect); update(); }));
  app.querySelector('[data-select-all]')?.addEventListener('change', e => { const shown = filteredCases().slice((state.casePage-1)*5,state.casePage*5).map(x=>x.id); state.selectedCases = e.target.checked ? [...new Set([...state.selectedCases,...shown])] : state.selectedCases.filter(x=>!shown.includes(x)); update(); });
  app.querySelectorAll('[data-case-page]').forEach(el => el.addEventListener('click', () => { state.casePage = Number(el.dataset.casePage); update(); }));
  app.querySelectorAll('[data-sort]').forEach(el => el.addEventListener('click', () => { state.sortDir = state.sortBy === el.dataset.sort && state.sortDir === 'asc' ? 'desc' : 'asc'; state.sortBy = el.dataset.sort; update(); }));
  app.querySelectorAll('[data-notice-filter]').forEach(el => el.addEventListener('click', () => { state.noticeFilter = el.dataset.noticeFilter; update(); }));
  app.querySelectorAll('[data-column]').forEach(el => el.addEventListener('change', () => { state.columns[el.dataset.column] = el.checked; update(); state.modal = {type:'columns'}; }));
  app.querySelectorAll('[data-toggle]').forEach(el => el.addEventListener('click', () => { el.classList.toggle('on'); toast('Setting updated in local demo'); }));
  app.querySelectorAll('[data-role-user]').forEach(el => el.addEventListener('change', () => toast(`Role updated for ${el.dataset.roleUser} in local demo`)));
  app.querySelectorAll('[data-filter]').forEach(el => el.addEventListener('input', () => { state.caseQuery = el.value; state.casePage = 1; const start = el.selectionStart; render(); const next = document.querySelector(`[data-filter="${el.dataset.filter}"]`); if(next){ next.focus(); next.setSelectionRange(start,start); } }));
  app.querySelectorAll('[data-close-modal]').forEach(el => el.addEventListener('click', e => { if (e.target === el || e.currentTarget === el) { state.modal=null; update(); } }));
  app.querySelectorAll('[data-upload-zone] label').forEach(el => el.addEventListener('click', () => document.querySelector('#registration-upload')?.click()));
  document.querySelector('#registration-upload')?.addEventListener('change', e => { const files = [...e.target.files]; const invalid = files.find(f => f.size > 10*1024*1024 || !/\.(pdf|docx|xlsx|jpg|jpeg|png)$/i.test(f.name)); if (invalid) { toast(`File rejected: ${invalid.name}. Use an accepted type up to 10MB.`, true); return; } state.registrationData.files = [...(state.registrationData.files||[]), ...files.map(f=>({name:f.name,size:`${Math.round(f.size/1024)} KB`}))]; toast(`${files.length} file${files.length>1?'s':''} added to local draft`); update(); });
  document.querySelector('#doc-upload')?.addEventListener('change', e => { const file = e.target.files?.[0]; if (!file) return; if (file.size > 10*1024*1024 || !/\.(pdf|docx|xlsx|jpg|jpeg|png)$/i.test(file.name)) { toast(`File rejected: ${file.name}. Use an accepted type up to 10MB.`, true); return; } state.modal = null; toast(`${file.name} passed frontend validation and was added to the local demo`); update(); });
  app.querySelectorAll('[data-remove-file]').forEach(el => el.addEventListener('click', () => { state.registrationData.files = (state.registrationData.files||[]).filter(f=>f.name!==el.dataset.removeFile); update(); }));
}

document.addEventListener('click', e => {
  const el = e.target.closest('[data-action]'); if (!el) return; state.lastActionEl = el; const action = el.dataset.action;
  if (action === 'login') { const email = document.querySelector('#login-email')?.value; const password = document.querySelector('#login-password')?.value; if (!email || !password) { toast('Enter a demo email and password to continue.', true); return; } state.role = document.querySelector('#login-role')?.value || state.role; state.auth = true; state.page='dashboard'; update(); toast(`Signed in as ${state.role}`); return; }
  if (action === 'toggle-lang') { state.lang = state.lang === 'en' ? 'bn' : 'en'; update(); return; }
  if (action === 'sign-out') { state.auth = false; state.page = 'dashboard'; state.modal = null; update(); return; }
  if (action === 'toggle-sidebar') { document.querySelector('#sidebar')?.classList.toggle('open'); return; }
  if (action === 'go-registration') { state.page='registration'; state.registrationStep=1; update(); return; }
  if (action === 'go-dashboard') { state.page='dashboard'; update(); return; }
  if (action === 'go-cases') { state.page='cases'; update(); return; }
  if (action === 'go-workflow') { state.page='workflow'; update(); return; }
  if (action.startsWith('open-case:')) { state.routeCase = action.split(':')[1]; state.page='case-detail'; state.detailsTab='summary'; update(); return; }
  if (action.startsWith('preview-doc:')) { state.modal={type:'preview',id:action.split(':')[1]}; update(); return; }
  if (action === 'columns-modal') { state.modal={type:'columns'}; update(); return; }
  if (action === 'close-modal') { state.modal=null; update(); return; }
  if (action === 'toggle-filters') { state.showFilters = !state.showFilters; update(); return; }
  if (action === 'clear-filters') { state.caseQuery=''; state.caseStatus='all'; state.casePriority='all'; state.caseOrg='all'; state.savedView='all'; state.casePage=1; update(); return; }
  if (action === 'bulk-archive') { state.modal={type:'confirm',message:`Archive ${state.selectedCases.length} selected case record${state.selectedCases.length>1?'s':''}?`,action:'confirm-archive'}; update(); return; }
  if (action === 'confirm-archive') { state.selectedCases=[]; state.modal=null; toast('Selected cases archived in local demo'); update(); return; }
  if (action === 'bulk-assign') { toast('Bulk assignment flow opened for selected cases'); return; }
  if (action === 'export-cases') { downloadCsv('mohpw-cases.csv', filteredCases()); return; }
  if (action === 'export-dashboard' || action === 'export-report' || action === 'export-documents' || action === 'export-users' || action === 'export-workflow' || action === 'export-case') { toast('Export prepared in the local demo'); return; }
  if (action === 'retry') { state.loading=true; update(); setTimeout(()=>{state.loading=false; toast('The saved local view is ready'); update();},700); return; }
  if (action === 'save-draft') { collectRegistration(); toast('Draft saved locally for this session'); return; }
  if (action === 'registration-next') { collectRegistration(); const required = state.registrationStep === 1 ? ['title','organization','court','category','summary'] : state.registrationStep === 2 ? ['assignee','filingDate','deadline'] : []; const missing = required.filter(k=>!state.registrationData[k]); if(missing.length){ toast('Complete the required fields before continuing.',true); update(); return; } state.registrationStep++; update(); return; }
  if (action === 'registration-back') { collectRegistration(); state.registrationStep--; update(); return; }
  if (action === 'submit-registration') { collectRegistration(); state.modal={type:'confirm',message:'Submit this fictional case record for workflow processing?',action:'confirm-submit'}; update(); return; }
  if (action === 'confirm-submit') { state.modal=null; state.page='cases'; toast('Case submitted to the local demo register'); update(); return; }
  if (action === 'upload-document') { state.modal={type:'upload'}; update(); return; }
  if (action === 'mark-all-read') { notifications.forEach(n=>n.read=true); toast('All notifications marked as read'); update(); return; }
  if (action.startsWith('mark-read:')) { const n=notifications.find(x=>x.id===Number(action.split(':')[1])); if(n)n.read=true; update(); return; }
  if (action === 'complete-task') { toast('Task marked complete in local demo'); return; }
  if (action === 'assign-task') { toast('Assignment panel opened'); return; }
  if (action === 'save-settings') { toast('Settings saved for this session'); return; }
  if (action === 'print') { toast('Print preview requested'); return; }
  if (action.startsWith('toast:')) { toast(action.slice(6)); return; }
});

document.addEventListener('change', e => { if(e.target.id === 'case-status'){state.caseStatus=e.target.value;state.casePage=1;update();} if(e.target.id === 'case-priority'){state.casePriority=e.target.value;state.casePage=1;update();} if(e.target.id === 'case-org'){state.caseOrg=e.target.value;state.casePage=1;update();} if(e.target.id === 'saved-view'){state.savedView=e.target.value;state.casePage=1;update();} });
document.addEventListener('keydown', e => { if (e.key === 'Escape' && state.modal) { state.modal=null; update(); return; } if (e.key === 'Escape') document.querySelector('#sidebar')?.classList.remove('open'); });

function downloadCsv(name, rows) { const head = Object.keys(rows[0] || {id:'',title:''}); const csv = [head.join(','), ...rows.map(r=>head.map(k=>`"${String(r[k] ?? '').replace(/"/g,'""')}"`).join(','))].join('\n'); const url = URL.createObjectURL(new Blob([csv],{type:'text/csv'})); const a=document.createElement('a'); a.href=url; a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(url),1000); toast('CSV export downloaded'); }

render();
